<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';
use InaudisVote\Core\Authorization;use InaudisVote\Core\Csrf;use InaudisVote\Core\Navigation;use InaudisVote\Services\OrganizationService;use InaudisVote\Services\UserService;
$user=Authorization::requireRoles(['admin','organizer']);$error=null;$message=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Csrf::validate($_POST['_csrf']??null))$error='Solicitud inválida.';
 else try{$action=(string)($_POST['action']??'create');if($action==='toggle'){UserService::toggleStatus((int)($_POST['user_id']??0),$user);$message='Estado actualizado.';}else{UserService::create($_POST,$user);$message='Usuario creado.';}}catch(Throwable $exception){$error=$exception->getMessage();}
}
$users=UserService::allForActor($user);$organizations=$user['role']==='admin'?OrganizationService::all():[];
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Equipo y accesos | QUORUM</title><link rel="stylesheet" href="/assets/quorum.css"><link rel="stylesheet" href="/assets/password-toggle.css"></head><body class="vota-ui"><div class="v-shell">
<?php Navigation::sidebar($user, 'users'); ?>
<div class="v-main"><header class="v-topbar"><span class="v-muted">Administración de accesos</span><span style="flex:1"></span><a class="v-link" href="/logout.php">Salir</a></header><main class="v-content">
<div class="v-headrow"><div><div class="v-kicker">Accesos y responsabilidades</div><h1 class="v-title">Equipo</h1><div class="v-accent-line"></div><p class="v-subtitle"><?=$user['role']==='admin'?'Administra usuarios de toda la plataforma.':'Administra organizadores y Ministros de Fe de tu cliente.'?></p></div></div>
<?php if($message):?><div class="v-alert v-alert-ok"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="v-alert v-alert-error"><?=htmlspecialchars($error)?></div><?php endif;?>
<div class="v-grid-2"><section class="v-card v-pad"><h2 style="margin-top:0">Nuevo usuario</h2><form method="post" class="v-stack"><?=Csrf::input()?><input type="hidden" name="action" value="create"><input class="v-field" name="name" required placeholder="Nombre"><input class="v-field" name="email" type="email" required placeholder="Email"><input class="v-field" name="password" type="password" minlength="8" required placeholder="Contraseña inicial"><select class="v-field" name="role"><option value="organizer">Organizador</option><option value="witness">Ministro de Fe</option><?php if($user['role']==='admin'):?><option value="admin">Administrador INAUDIS</option><?php endif;?></select><?php if($user['role']==='admin'):?><select class="v-field" name="organization_id"><option value="">Sin organización / Admin</option><?php foreach($organizations as $organization):?><option value="<?=$organization['id']?>"><?=htmlspecialchars($organization['name'])?></option><?php endforeach;?></select><?php endif;?><button class="v-btn v-btn-orange">Crear usuario</button></form></section>
<section class="v-card v-pad v-table-wrap"><div class="v-section-head"><h2 style="margin:0">Accesos</h2><span class="v-muted"><?=count($users)?> usuarios</span></div><table class="v-table"><thead><tr><th>Nombre</th><th>Email</th><th>Rol</th><th>Cliente</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($users as $account):?><tr><td><strong><?=htmlspecialchars($account['name'])?></strong></td><td><?=htmlspecialchars($account['email'])?></td><td><?=htmlspecialchars($account['role'])?></td><td><?=htmlspecialchars((string)$account['organization_name'])?></td><td><span class="v-status <?=$account['status']==='active'?'v-status-open':'v-status-draft'?>"><?=htmlspecialchars($account['status'])?></span></td><td><?php if((int)$account['id']!==(int)$user['id']):?><form method="post" onsubmit="return confirm('¿Cambiar el estado de este acceso?');"><?=Csrf::input()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="user_id" value="<?=$account['id']?>"><button class="v-btn v-btn-outline">Cambiar estado</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section></div>
</main></div></div></body></html>
